/**
 * Core YAML validation module.
 *
 * Provides functions for validating YAML syntax from strings and files
 * using Bun's built-in YAML parser.
 */

/** Result of a YAML validation operation. */
export interface YamlValidationResult {
  /** Whether the YAML content is syntactically valid. */
  valid: boolean;
  /** The file path that was validated (if file-based). */
  filePath?: string;
  /** Error message if validation failed. */
  error?: string;
}

/**
 * Validate a YAML string for syntactic correctness.
 */
export function validateYamlString(content: string): YamlValidationResult {
  try {
    YAML.parse(content);
    return { valid: true };
  } catch (error: unknown) {
    if (error instanceof SyntaxError) {
      return { valid: false, error: error.message };
    }
    const message =
      error instanceof Error ? error.message : String(error);
    return { valid: false, error: `Unexpected error: ${message}` };
  }
}

/**
 * Validate a YAML file by path.
 */
export async function validateYamlFile(
  filePath: string,
): Promise<YamlValidationResult> {
  try {
    const file = Bun.file(filePath);
    const exists = await file.exists();

    if (!exists) {
      return { valid: false, filePath, error: `File not found: ${filePath}` };
    }

    const content = await file.text();
    const result = validateYamlString(content);
    return { ...result, filePath };
  } catch (error: unknown) {
    const message =
      error instanceof Error ? error.message : String(error);
    return { valid: false, filePath, error: message };
  }
}

