/**
 * CLI entry point for the YAML validator.
 *
 * Parses command-line arguments, invokes the core validator,
 * formats output, and sets the appropriate exit code.
 */

import { validateYamlFile } from "./yaml-validator";

const USAGE = `Usage: bun run validate-yaml <file>

Validate the syntax of a YAML file.

Arguments:
  file    Path to the YAML file to validate

Exit codes:
  0       YAML is valid
  1       YAML is invalid or an error occurred`;

const filePath = process.argv[2];

if (!filePath || filePath === "--help") {
  console.error(USAGE);
  process.exit(1);
}

const result = await validateYamlFile(filePath);

if (result.valid) {
  console.log(`${result.filePath} is valid YAML`);
  process.exit(0);
} else {
  if (result.error?.startsWith("File not found:")) {
    console.error(`Error: ${result.error}`);
  } else {
    console.error(`Error: ${result.filePath} is not valid YAML\n${result.error}`);
  }
  process.exit(1);
}

