import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { join } from "path";
import { tmpdir } from "os";
import { validateYamlString, validateYamlFile } from "./yaml-validator";

const testDir = join(tmpdir(), `yaml-validator-test-${process.pid}`);
const validYamlPath = join(testDir, "valid.yaml");
const invalidYamlPath = join(testDir, "invalid.yaml");
const nonExistentPath = join(testDir, "does-not-exist.yaml");

beforeAll(async () => {
  await Bun.write(validYamlPath, "name: test\nversion: 1\n");
  await Bun.write(invalidYamlPath, "items: [1, 2, 3\n");
});

afterAll(async () => {
  const { rm } = await import("fs/promises");
  await rm(testDir, { recursive: true, force: true });
});

describe("validateYamlString", () => {
  test("returns valid for simple YAML", () => {
    const result = validateYamlString("name: test\nversion: 1");
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for nested YAML", () => {
    const result = validateYamlString("parent:\n  child: value");
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns invalid with error for malformed YAML", () => {
    const result = validateYamlString("items: [1, 2, 3\n");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
    expect(result.error!.length).toBeGreaterThan(0);
  });

  test("returns valid for empty string", () => {
    const result = validateYamlString("");
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });
});

describe("validateYamlFile", () => {
  test("returns valid for a file with correct YAML", async () => {
    const result = await validateYamlFile(validYamlPath);
    expect(result.valid).toBe(true);
    expect(result.filePath).toBe(validYamlPath);
    expect(result.error).toBeUndefined();
  });

  test("returns invalid with error for a file with malformed YAML", async () => {
    const result = await validateYamlFile(invalidYamlPath);
    expect(result.valid).toBe(false);
    expect(result.filePath).toBe(invalidYamlPath);
    expect(result.error).toBeDefined();
    expect(result.error!.length).toBeGreaterThan(0);
  });

  test("returns file-not-found error for non-existent path", async () => {
    const result = await validateYamlFile(nonExistentPath);
    expect(result.valid).toBe(false);
    expect(result.filePath).toBe(nonExistentPath);
    expect(result.error).toStartWith("File not found:");
  });
});

