     1→/**
     2→ * Core YAML validation module.
     3→ *
     4→ * Provides functions for validating YAML syntax from strings and files
     5→ * using Bun's built-in YAML parser.
     6→ */
     7→
     8→import { YAML } from "bun";
     9→
    10→/** Result of a YAML validation operation. */
    11→export interface YamlValidationResult {
    12→  /** Whether the YAML content is syntactically valid. */
    13→  valid: boolean;
    14→  /** The file path that was validated (if file-based). */
    15→  filePath?: string;
    16→  /** Error message if validation failed. */
    17→  error?: string;
    18→}
    19→
    20→/**
    21→ * Validate a YAML string for syntactic correctness.
    22→ */
    23→export function validateYamlString(content: string): YamlValidationResult {
    24→  try {
    25→    YAML.parse(content);
    26→    return { valid: true };
    27→  } catch (error: unknown) {
    28→    if (error instanceof SyntaxError) {
    29→      return { valid: false, error: error.message };
    30→    }
    31→    const message =
    32→      error instanceof Error ? error.message : String(error);
    33→    return { valid: false, error: `Unexpected error: ${message}` };
    34→  }
    35→}
    36→
    37→/**
    38→ * Validate a YAML file by path.
    39→ */
    40→export async function validateYamlFile(
    41→  filePath: string,
    42→): Promise<YamlValidationResult> {
    43→  try {
    44→    const file = Bun.file(filePath);
    45→    const exists = await file.exists();
    46→
    47→    if (!exists) {
    48→      return { valid: false, filePath, error: `File not found: ${filePath}` };
    49→    }
    50→
    51→    const content = await file.text();
    52→    const result = validateYamlString(content);
    53→    return { ...result, filePath };
    54→  } catch (error: unknown) {
    55→    const message =
    56→      error instanceof Error ? error.message : String(error);
    57→    return { valid: false, filePath, error: message };
    58→  }
    59→}
