**`/private/tmp/rp1-evals/6039d564/workspace/src/yaml-validator.ts`** exports:

- **`YamlValidationResult`** interface with `valid: boolean`, `filePath?: string`, `error?: string`
- **`validateYamlString(content: string): YamlValidationResult`** -- wraps `YAML.parse()` (imported from `"bun"`) in try/catch. Returns `{ valid: true }` on success, `{ valid: false, error: <message> }` on `SyntaxError`, and handles unexpected errors with a prefixed message.
- **`validateYamlFile(filePath: string): Promise<YamlValidationResult>`** -- checks file existence via `Bun.file(filePath).exists()`, reads via `.text()`, delegates to `validateYamlString`, and spreads the result with `filePath`. Outer try/catch handles file I/O errors (e.g. permission denied).

```typescript
import { YAML } from "bun";

export interface YamlValidationResult {
  valid: boolean;
  filePath?: string;
  error?: string;
}

export function validateYamlString(content: string): YamlValidationResult {
  try {
    YAML.parse(content);
    return { valid: true };
  } catch (error: unknown) {
    if (error instanceof SyntaxError) {
      return { valid: false, error: error.message };
    }
    const message = error instanceof Error ? error.message : String(error);
    return { valid: false, error: `Unexpected error: ${message}` };
  }
}

export async function validateYamlFile(
  filePath: string,
): Promise<YamlValidationResult> {
  try {
    const file = Bun.file(filePath);
    const exists = await file.exists();
    if (!exists) {
      return { valid: false, filePath, error: `File not found: ${filePath}` };
    }
    const content = await file.text();
    const result = validateYamlString(content);
    return { ...result, filePath };
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    return { valid: false, filePath, error: message };
  }
}
